UPDATE t_inquiry
SET deleted = #{deletedAt}
WHERE id = #{id}
  AND deleted = 0

UPDATE t_inquiry
SET inquiry_status = #{status}
WHERE id = #{id}
  AND deleted = 0

UPDATE t_inquiry
SET first_reply_at = #{firstReplyAt}
WHERE id = #{id}
  AND deleted = 0
  AND first_reply_at IS NULL

